fn sum(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // It's assumed that a.len() == b.len() and len <= 100,
    // and that for each index i, a[i] + b[i] < 1000.
    let mut c = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        c.push(a[i] + b[i]);
    }
    c
}

